sparql:
PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?paper ?paperLabel ?annotatorAgreementLabel ?intercoderReliabilityMetricLabel ?conflictResolutionLabel ?measuredAgreementLabel WHERE {
  ?paper orkgp:P31 ?contribution .
  ?contribution a orkgc:C121001 .
  ?contribution orkgp:P181031 ?annotationProcess .
  ?annotationProcess orkgp:P181041 ?annotatorAgreement .
  OPTIONAL { ?annotatorAgreement rdfs:label ?annotatorAgreementLabel }
  OPTIONAL {
    ?annotatorAgreement orkgp:P181042 ?intercoderReliabilityMetric .
    ?intercoderReliabilityMetric rdfs:label ?intercoderReliabilityMetricLabel
  }
  OPTIONAL {
    ?annotatorAgreement orkgp:P181044 ?conflictResolution .
    ?conflictResolution rdfs:label ?conflictResolutionLabel
  }
  OPTIONAL {
    ?annotatorAgreement orkgp:P181045 ?measuredAgreement .
    BIND(STR(?measuredAgreement) AS ?measuredAgreementLabel)
  }
  OPTIONAL { ?paper rdfs:label ?paperLabel }
}
ORDER BY ?paperLabel

PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?paper ?paperLabel ?dataset ?datasetItems ?reTaskLabel ?nlpTaskTypeLabel ?publicAvailabilityLabel WHERE {
  ?paper orkgp:P31 ?contribution .
  ?contribution a orkgc:C121001 .
  ?contribution orkgp:P181011 ?dataset .
  OPTIONAL { ?dataset orkgp:P181015 ?datasetItems }
  OPTIONAL {
    ?contribution orkgp:P181002 ?reTask .
    ?reTask rdfs:label ?reTaskLabel
  }
  OPTIONAL {
    ?contribution orkgp:P181003 ?nlpTask .
    ?nlpTask orkgp:P181004 ?nlpTaskType .
    ?nlpTaskType rdfs:label ?nlpTaskTypeLabel
  }
  OPTIONAL {
    ?dataset orkgp:license ?license .
    ?license orkgp:P181026 ?publicAvailability .
    ?publicAvailability rdfs:label ?publicAvailabilityLabel
  }
  OPTIONAL { ?paper rdfs:label ?paperLabel }
}
ORDER BY ?paperLabel

PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?paper ?paperLabel ?nlpTaskTypeLabel ?annotatorCount WHERE {
  ?paper orkgp:P31 ?contribution .
  ?contribution a orkgc:C121001 .
  ?contribution orkgp:P181003 ?nlpTask .
  ?nlpTask orkgp:P181004 ?nlpTaskType .
  ?nlpTaskType rdfs:label ?nlpTaskTypeLabel .
  OPTIONAL {
    ?contribution orkgp:P181031 ?annotationProcess .
    ?annotationProcess orkgp:P181032 ?annotator .
    OPTIONAL { ?annotator orkgp:P59120 ?annotatorNumber }
  }
  BIND(COALESCE(STR(?annotatorNumber), "not reported") AS ?annotatorCount)
  OPTIONAL { ?paper rdfs:label ?paperLabel }
}
ORDER BY ?paperLabel
